function f(n){if(n._ribbonPolygons)return n._ribbonPolygons;if(n.shape!=="brick")return[];if(n.curveSlices?.length>=2){let t=n.height/2,m=[];for(let e=1;e<n.curveSlices.length;e++){let h=n.curveSlices[e-1],r=n.curveSlices[e];m.push([[h.x+h.nx*t,h.y+h.ny*t],[r.x+r.nx*t,r.y+r.ny*t],[r.x-r.nx*t,r.y-r.ny*t],[h.x-h.nx*t,h.y-h.ny*t]]);let x=r.x-h.x,s=r.y-h.y,y=Math.hypot(x,s);if(y>1e-6){let u=-s/y*t,p=x/y*t;m.push([[h.x+u,h.y+p],[r.x+u,r.y+p],[r.x-u,r.y-p],[h.x-u,h.y-p]])}}return m}let a=Math.cos(n.angle),i=Math.sin(n.angle);return[[[-1,-1],[1,-1],[1,1],[-1,1]].map(([t,m])=>[n.x+t*n.width/2*a-m*n.height/2*i,n.y+t*n.width/2*i+m*n.height/2*a])]}function M(n){if(n._ribbonBounds)return n._ribbonBounds;if(n.shape==="circle")return{minX:n.x-n.radius,maxX:n.x+n.radius,minY:n.y-n.radius,maxY:n.y+n.radius};let a=f(n).flat();return{minX:Math.min(...a.map(i=>i[0])),maxX:Math.max(...a.map(i=>i[0])),minY:Math.min(...a.map(i=>i[1])),maxY:Math.max(...a.map(i=>i[1]))}}function X(n){if(!n.length)return{minX:0,maxX:0,minY:0,maxY:0,width:0,height:0};let a=n.map(M),i={minX:Math.min(...a.map(t=>t.minX)),maxX:Math.max(...a.map(t=>t.maxX)),minY:Math.min(...a.map(t=>t.minY)),maxY:Math.max(...a.map(t=>t.maxY))};return{...i,width:i.maxX-i.minX,height:i.maxY-i.minY}}function c(n){return n.map((a,i)=>{let t=n[(i+1)%n.length],m=t[0]-a[0],e=t[1]-a[1],h=Math.hypot(m,e)||1;return[-e/h,m/h]})}function o(n,a){let i=1/0;for(let t of[...c(n),...c(a)]){let m=x=>x.map(s=>s[0]*t[0]+s[1]*t[1]),e=m(n),h=m(a),r=Math.min(Math.max(...e),Math.max(...h))-Math.max(Math.min(...e),Math.min(...h));if(r<=0)return r;i=Math.min(i,r)}return i}function d(n,a){let i=c(a),t=a[0];for(let x of a)Math.hypot(x[0]-n.x,x[1]-n.y)<Math.hypot(t[0]-n.x,t[1]-n.y)&&(t=x);let m=t[0]-n.x,e=t[1]-n.y,h=Math.hypot(m,e);h>1e-9&&i.push([m/h,e/h]);let r=1/0;for(let x of i){let s=a.map(p=>p[0]*x[0]+p[1]*x[1]),y=n.x*x[0]+n.y*x[1],u=Math.min(Math.max(...s),y+n.radius)-Math.max(Math.min(...s),y-n.radius);if(u<=0)return u;r=Math.min(r,u)}return r}function l(n,a){if(n.shape==="circle"&&a.shape==="circle")return n.radius+a.radius-Math.hypot(n.x-a.x,n.y-a.y);if(a.shape==="circle")return l(a,n);let i=M(n),t=M(a);return i.maxX<=t.minX||t.maxX<=i.minX||i.maxY<=t.minY||t.maxY<=i.minY?-1:n.shape==="circle"?Math.max(...f(a).map(m=>d(n,m))):Math.max(...f(n).flatMap(m=>f(a).map(e=>o(m,e))))}export{M as a,X as b,l as c};
